import { useEffect, useState } from "react";

/**
 * Subscribe to a CSS media query.
 *
 * Returns `true` while the document matches `query`, and re-renders
 * whenever the match state changes. Requires `window.matchMedia`
 * (present in real browsers; install a test double under jsdom).
 */
export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState<boolean>(() => {
    const mql = window.matchMedia(query);
    return mql.matches;
  });

  useEffect(() => {
    const mql = window.matchMedia(query);

    // Sync in case the query's state changed between render and effect,
    // or between the initial render and subsequent renders.
    setMatches(mql.matches);

    const onChange = (event: MediaQueryListEvent) => {
      setMatches(event.matches);
    };

    mql.addEventListener("change", onChange);
    return () => {
      mql.removeEventListener("change", onChange);
    };
  }, [query]);

  return matches;
}

/** Convenience hook for the `prefers-color-scheme` media feature. */
export function usePrefersDark(): boolean {
  return useMediaQuery("(prefers-color-scheme: dark)");
}

