/**
 * A test double for `MediaQueryList` + `window.matchMedia`, since jsdom
 * does not implement either.
 *
 * Each double is a MediaQueryList-like object whose `matches` flag can be
 * flipped programmatically; flipping it dispatches a `change` event to all
 * registered listeners. `addEventListener`/`removeEventListener` calls are
 * recorded so tests can assert exact listener references were cleaned up.
 */

export type ChangeListener = (event: MediaQueryListEvent) => void;

export interface FakeMediaQueryList {
  media: string;
  matches: boolean;
  onchange: ChangeListener | null;
  addEventListener: (type: "change", listener: ChangeListener) => void;
  removeEventListener: (type: "change", listener: ChangeListener) => void;
  dispatchEvent: (event: Event) => boolean;

  /** Test controls — not part of the real MediaQueryList API. */
  __setMatches: (value: boolean) => void;
  __addedListeners: ChangeListener[];
  __removedListeners: ChangeListener[];
}

export interface MatchMediaDouble {
  /** The function to install as `window.matchMedia`. */
  matchMedia: (query: string) => FakeMediaQueryList;
  /** Flip `matches` for every list created for `query` and fire `change`. */
  setMatches: (query: string, value: boolean) => void;
  /** All lists created for `query`, in creation order. */
  listsFor: (query: string) => FakeMediaQueryList[];
}

export function createMatchMediaDouble(): MatchMediaDouble {
  const listsByQuery = new Map<string, FakeMediaQueryList[]>();

  const matchMedia = (query: string): FakeMediaQueryList => {
    const listeners = new Set<ChangeListener>();
    const list: FakeMediaQueryList = {
      media: query,
      matches: false,
      onchange: null,

      addEventListener(type, listener) {
        if (type !== "change") return;
        list.__addedListeners.push(listener);
        listeners.add(listener);
      },

      removeEventListener(type, listener) {
        if (type !== "change") return;
        list.__removedListeners.push(listener);
        listeners.delete(listener);
      },

      dispatchEvent(event) {
        if (event.type === "change") {
          for (const listener of [...listeners]) {
            listener(event as unknown as MediaQueryListEvent);
          }
          list.onchange?.(event as unknown as MediaQueryListEvent);
        }
        return true;
      },

      __setMatches(value: boolean) {
        if (list.matches === value) return; // no event on no-op flips
        list.matches = value;
        // Real browsers dispatch a MediaListChangeEvent with `matches`
        // reflecting the new state and `media` the query string.
        const event = { type: "change", matches: value, media: query };
        list.dispatchEvent(event as unknown as Event);
      },

      __addedListeners: [],
      __removedListeners: [],
    };

    const existing = listsByQuery.get(query);
    if (existing) existing.push(list);
    else listsByQuery.set(query, [list]);

    return list;
  };

  return {
    matchMedia,
    setMatches(query, value) {
      for (const list of listsByQuery.get(query) ?? []) {
        list.__setMatches(value);
      }
    },
    listsFor: (query) => listsByQuery.get(query) ?? [],
  };
}

