import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useMediaQuery, usePrefersDark } from "../src/use-media-query.js";
import {
  createMatchMediaDouble,
  type MatchMediaDouble,
} from "./fake-match-media.js";

const DARK = "(prefers-color-scheme: dark)";
let double: MatchMediaDouble;

beforeEach(() => {
  // jsdom has no matchMedia — install the test double before renderHook.
  double = createMatchMediaDouble();
  window.matchMedia = double.matchMedia as typeof window.matchMedia;
});

afterEach(() => {
  delete (window as { matchMedia?: unknown }).matchMedia;
});

describe("useMediaQuery", () => {
  it("returns the initial value from matches", () => {
    const mql = double.matchMedia(DARK);
    mql.__setMatches(true);

    const { result } = renderHook(() => useMediaQuery(DARK));
    expect(result.current).toBe(true);
  });

  it("defaults to false when nothing matched", () => {
    const { result } = renderHook(() => useMediaQuery(DARK));
    expect(result.current).toBe(false);
  });

  it("re-renders when the double fires a change event", () => {
    const { result } = renderHook(() => useMediaQuery(DARK));
    expect(result.current).toBe(false);

    act(() => {
      double.setMatches(DARK, true);
    });
    expect(result.current).toBe(true);

    act(() => {
      double.setMatches(DARK, false);
    });
    expect(result.current).toBe(false);
  });

  it("removes exactly the listener it registered on unmount", () => {
    const { unmount } = renderHook(() => useMediaQuery(DARK));

    const [mql] = double.listsFor(DARK);
    expect(mql.__addedListeners).toHaveLength(1);
    const added = mql.__addedListeners[0];

    unmount();

    expect(mql.__removedListeners).toContain(added);
    expect(mql.__removedListeners[mql.__removedListeners.length - 1]).toBe(added);

    // The listener set is now empty: flipping matches fires no handlers.
    expect(() =>
      act(() => {
        double.setMatches(DARK, true);
      }),
    ).not.toThrow();
    // And no stray React state update warnings: no listeners remain.
    expect(mql.__removedListeners).toEqual(mql.__addedListeners);
  });

  it("keeps hooks on different queries independent", () => {
    const LIGHT = "(prefers-color-scheme: light)";
    const { result: dark, rerender } = renderHook(() => ({
      dark: useMediaQuery(DARK),
      light: useMediaQuery(LIGHT),
    }));

    expect(dark.current.dark).toBe(false);
    expect(dark.current.light).toBe(false);

    act(() => {
      double.setMatches(DARK, true);
    });
    expect(dark.current.dark).toBe(true);
    expect(dark.current.light).toBe(false);

    // A separate hook instance for LIGHT, mounted later, is unaffected by
    // DARK flips and vice versa.
    const other = renderHook(() => useMediaQuery(LIGHT));
    act(() => {
      double.setMatches(LIGHT, true);
    });
    expect(other.result.current).toBe(true);
    expect(dark.current.dark).toBe(true); // untouched

    act(() => {
      double.setMatches(DARK, false);
    });
    rerender();
    expect(dark.current.dark).toBe(false);
    expect(other.result.current).toBe(true); // still untouched
  });
});

describe("usePrefersDark", () => {
  it("tracks the prefers-color-scheme: dark query", () => {
    const { result } = renderHook(() => usePrefersDark());
    expect(result.current).toBe(false);

    act(() => {
      double.setMatches(DARK, true);
    });
    expect(result.current).toBe(true);
  });
});

